// Função para calcular Rogers-Satchell
double CalculateRogersSatchell(string symbol, ENUM_TIMEFRAMES tf, int period) {
   double sum = 0.0;
   for(int i = 0; i < period; i++) {
      double high = iHigh(symbol, tf, i);
      double low = iLow(symbol, tf, i);
      double close = iClose(symbol, tf, i);
      double open = iOpen(symbol, tf, i);

      if(high > 0 && low > 0 && close > 0 && open > 0) {
         double hc = MathLog(high / close);
         double ho = MathLog(high / open);
         double lc = MathLog(low / close);
         double lo = MathLog(low / open);
         sum += (hc * ho) + (lc * lo);
      }
   }
   return MathSqrt(sum / period);
}

