// Função para calcular SATR (Spread-Adjusted ATR)
double CalculateSATR(string symbol, ENUM_TIMEFRAMES tf, int atr_period, double alpha) {
   double atr = iATR(symbol, tf, atr_period);
   double spread = SymbolInfoInteger(symbol, SYMBOL_SPREAD) * SymbolInfoDouble(symbol, SYMBOL_POINT);
   return atr + (alpha * spread);
}

