// Função para decidir qual métrica usar
double GetVolatilityMetric(string symbol, ENUM_TIMEFRAMES tf) {
   double rs = CalculateRogersSatchell(symbol, tf, 20);
   double satr = CalculateSATR(symbol, tf, 14, 0.5);
   double spread = SymbolInfoInteger(symbol, SYMBOL_SPREAD) * SymbolInfoDouble(symbol, SYMBOL_POINT);

   // Calcular média móvel RS para validação
   double rs_ma = CalculateRSMA(symbol, tf, 50);

   // Decision tree
   if(rs > 0.5 * rs_ma && rs < 2.5 * rs_ma) {
      // Plano A: RS válido
      return rs;
   }
   else if(rs < 0.7 * rs_ma || spread > 3 * SymbolInfoDouble(symbol, SYMBOL_POINT)) {
      // Plano B: SATR Blend
      return 0.7 * satr + 0.3 * rs;
   }
   else {
      // Plano C: Fallback tabela
      return GetFixedVolatilityBySession(symbol);
   }
}
